    "title": "Cropline Telemetry \u2014 agricultural irrigation-scheduling API for connected drip systems API",
    "served_at": "/openapi.json",
    "description": "OpenAPI 3.1 spec for the Cropline Telemetry \u2014 agricultural irrigation-scheduling API for connected drip systems API, inlined below. All endpoints are relative paths on the same host; construct requests with execute().",
    "document": {
      "openapi": "3.1.0",
      "info": {
        "title": "Cropline Telemetry \u2014 agricultural irrigation-scheduling API for connected drip systems API",
        "version": "1.0.0",
        "description": "A REST API that ingests soil-moisture sensor readings per field, builds an irrigation batch plan, commits the plan to in-field controllers, and confirms execution. Engineers integrate it into farm-ops backends and Postman flows."
      },
      "servers": [
        {
          "url": "http://localhost:9001"
        }
      ],
      "paths": {
        "/openapi.json": {
          "get": {
            "summary": "OpenAPI spec doc",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v3/oauth/token": {
          "post": {
            "summary": "OAuth client_credentials",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v3/fields": {
          "get": {
            "summary": "List fields with current moisture",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/plans": {
          "post": {
            "summary": "Create an irrigation plan draft",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/plans/{id}": {
          "get": {
            "summary": "Read a plan draft + committed state",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/plans/{id}/commit": {
          "post": {
            "summary": "Commit a plan to controllers",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/plans/{id}/confirm": {
          "get": {
            "summary": "Confirm execution status",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v1/plans": {
          "post": {
            "summary": "DEPRECATED draft create",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
